import { Roles } from '@/types/api.types';

/**
 * Mirrors the API's `Policies` class (AlumniApp.Api/Infra/RolePolicyProvider.cs).
 * Names match the C# constants exactly so the two stay easy to compare.
 * A group is satisfied when the user holds *any* role in it.
 */
export const Policies = {
  User: [Roles.User],
  EventMgr: [Roles.EventMgr],
  SchoolAdmin: [Roles.SchoolAdmin],
  BatchAdmin: [Roles.BatchAdmin],
  Admin: [Roles.Admin],
  SuperAdmin: [Roles.SuperAdmin],

  // Combined policies for convenience
  Admin_SuperAdmin: [Roles.Admin, Roles.SuperAdmin],
  EventMgr_Admin_SuperAdmin: [Roles.EventMgr, Roles.Admin, Roles.SuperAdmin],
  AnyAdmin: [Roles.SchoolAdmin, Roles.BatchAdmin, Roles.Admin, Roles.SuperAdmin],
} satisfies Record<string, Roles[]>;

// Returns true when the user is allowed by `requiredRole`. SuperAdmin always passes.
// `requiredRole` can be a single role, an array (any-of), or undefined (no requirement).
export const hasRequiredRole = (
  requiredRole: Roles | Roles[] | undefined,
  userRoles: Roles[],
): boolean => {
  if (!requiredRole) return true;
  if (userRoles.includes(Roles.SuperAdmin)) return true;
  const required = Array.isArray(requiredRole) ? requiredRole : [requiredRole];
  return required.some(r => userRoles.includes(r));
};

/** True when the user satisfies the given policy group. */
export const isInPolicy = (
  policy: Roles[],
  userRoles: Roles[],
): boolean => policy.some(r => userRoles.includes(r));
